import{boot,e,field,select,editAttrs}from'../creative-kit/ui.js?v=0.11.0';import{make,validate,apply,markdown,TYPES}from'./state.js?v=0.11.0';
const statuses={open:'Unanswered',hypothesis:'Working hypothesis',supported:'Supported by evidence I recorded'};
function card(q,w){return `<article class="card question" data-drag-id="${e(q.id)}"><div class="card-top"><span>${q.parent?q.relation+' of another question':'Open a different route'}</span><button class="drag-handle" data-drag-handle data-action="move-menu" data-id="${e(q.id)}" aria-label="Move ${e(q.question||'question')}">⠿</button></div><h3>${e(q.question||'Write your question…')}</h3><p>${e(q.unlocks||'What would answering this let you do differently?')}</p><div class="card-actions"><button class="text-button" data-action="edit" data-id="${e(q.id)}">Edit</button><button class="text-button" data-action="branch-menu" data-id="${e(q.id)}">Branch ↗</button><button class="pick ${w.selected.includes(q.id)?'picked':''}" data-action="select" data-id="${e(q.id)}" aria-pressed="${w.selected.includes(q.id)}">${w.selected.includes(q.id)?'✓ Selected':'Explore this'}</button></div></article>`;}
function render(w){return `<div class="phase-tabs" role="group" aria-label="Thinking phase"><button data-action="phase" data-phase="expand" aria-pressed="${w.phase==='expand'}">1 · Expand the questions</button><button data-action="phase" data-phase="develop" aria-pressed="${w.phase==='develop'}">2 · Explore selected questions (${w.selected.length})</button></div>${w.phase==='expand'?`<div class="section-head"><div><h2>Questions lead in different directions.</h2><p>Drag to change a question’s lens. Expand or invert it before settling on an answer.</p></div><button data-action="add">+ Question</button></div><div class="question-board">${Object.entries(TYPES).map(([key,label])=>`<section class="question-lane" data-drop-id="${key}"><h2>${label}</h2><p>${{fact:'What is happening? What is missing?',cause:'What produces the outcome?',value:'What should count as better?',design:'What could work differently?'}[key]}</p>${w.items.filter(q=>q.type===key).map(q=>card(q,w)).join('')||'<div class="empty">A different kind of question belongs here.</div>'}<button data-action="add" data-kind="${key}">+ ${label.replace('Possible designs','Design question')}</button></section>`).join('')}</div><section class="selection-well" data-drop-id="selected"><h2>${w.selected.length}/6 questions to explore</h2><p>Drop a question here to keep it for the next phase. Unselected questions stay on the board.</p><div class="selected-chips">${w.selected.map(id=>`<button data-action="select" data-id="${e(id)}">${e(w.items.find(q=>q.id===id).question||'Untitled')} ×</button>`).join('')}</div><button class="primary" data-action="phase" data-phase="develop">Explore selected questions →</button></section>`:`<div class="section-head"><div><h2>Keep answers provisional until you have evidence.</h2><p>Brainstorm beneath each question. A useful answer opens an action; it does not erase unresolved questions.</p></div></div><div class="develop-grid">${w.selected.map(id=>{const q=w.items.find(x=>x.id===id);return `<section class="panel"><span class="tag">${TYPES[q.type]}</span><h2>${e(q.question||'Untitled')}</h2>${field(`unlocks-${id}`,'If answered, what could change?',q.unlocks,editAttrs('items',id,'unlocks'))}${field(`answer-${id}`,'Provisional answer',q.answer,editAttrs('items',id,'answer'),'A possibility to examine, not a fact to assume.')}${select(`status-${id}`,'How are you treating this answer?',q.status,statuses,editAttrs('items',id,'status'))}${field(`evidence-${id}`,'Evidence or a way to find out',q.evidence,editAttrs('items',id,'evidence'),'What observation supports the answer? What could contradict it?')}${field(`ideas-${id}`,'Different approaches this opens',q.ideas,editAttrs('items',id,'ideas'),'Keep more than one possible response.')}</section>`;}).join('')||'<div class="empty">Select questions in the first phase to develop them here.</div>'}</div><p class="hint">${w.items.filter(q=>q.status==='open').length} questions remain unanswered in this workspace. A status is your judgment, not an automated verification.</p>`}`;}
function edit(id,k){const q=k.w().items.find(q=>q.id===id);k.open(field('q-question','Question',q.question,editAttrs('items',id,'question'))+select('q-type','Question lens',q.type,TYPES,editAttrs('items',id,'type'))+field('q-unlocks','What would an answer let you do differently?',q.unlocks,editAttrs('items',id,'unlocks'))+(q.parent?`<p class="hint">Branched from: ${e(k.w().items.find(p=>p.id===q.parent).question)}</p>`:'')+`<div class="toolbar"><button class="primary" data-action="close">Done</button><button class="delete" data-action="remove" data-id="${e(id)}" ${k.w().items.some(x=>x.parent===id)?'disabled':''}>Remove question</button></div>`,'Shape the question');}
boot({route:'questions',code:'S11',title:'Questions before answers',description:'Expand the questions that could open distinct approaches, then explore what answering them would change.',make,validate,apply,markdown,render,drop:(id,to,k)=>{if(to==='selected'){if(!k.w().selected.includes(id))k.act({type:'select',id});}else k.act({type:'move',id,kind:to});},handle:(a,d,k)=>{if(a==='edit')edit(d.id,k);else if(a==='add'){const id=k.uid();if(k.act({type:a,id,kind:d.kind}))edit(id,k);}else if(a==='branch-menu')k.open(`<div class="dialog-options"><button data-action="branch" data-parent="${e(d.id)}" data-relation="expand">Expand<span>What smaller question would make this answerable?</span></button><button data-action="branch" data-parent="${e(d.id)}" data-relation="invert">Invert<span>What changes if its premise is wrong?</span></button></div>`,'Branch the question');else if(a==='branch'){k.close();const id=k.uid();if(k.act({type:a,id,parent:d.parent,relation:d.relation}))edit(id,k);}else if(a==='move-menu')k.open('<div class="dialog-options">'+Object.entries(TYPES).map(([key,label])=>`<button data-action="move" data-id="${e(d.id)}" data-kind="${key}">${label}</button>`).join('')+'</div>','Change the lens');else if(a==='move'||a==='remove'){k.close();k.act({type:a,id:d.id,kind:d.kind});}else if(a==='select')k.act({type:a,id:d.id});else if(a==='phase')k.act({type:a,phase:d.phase},{checkpoint:false});}});
